/* docs: where to find the FiveM ID */
(function(){var D={"en":{"dc_denied_2":"Set FiveM ID to your own ID, like the line below. You find it in the server console: the line that says Denied shows the ID of the player who tried (fivem:… and steam:…)."},"no":{"dc_denied_2":"Sett FiveM ID til din egen ID, som linjen under. Du finner den i serverkonsollen: linjen som sier Denied viser ID-en til spilleren som prøvde (fivem:… og steam:…)."},"de":{"dc_denied_2":"Setze die FiveM ID auf deine eigene ID, wie in der Zeile unten. Du findest sie in der Serverkonsole: Die Zeile mit Denied zeigt die ID des Spielers, der es versucht hat (fivem:… und steam:…)."},"dk":{"dc_denied_2":"Sæt FiveM ID til dit eget ID, som linjen nedenfor. Du finder det i serverkonsollen: linjen med Denied viser ID'et på spilleren, der prøvede (fivem:… og steam:…)."},"es":{"dc_denied_2":"Pon en FiveM ID tu propio ID, como la línea de abajo. Lo encuentras en la consola del servidor: la línea que dice Denied muestra el ID del jugador que lo intentó (fivem:… y steam:…)."},"et":{"dc_denied_2":"Pane FiveM ID väljale oma ID, nagu allolev rida. Selle leiad serverikonsoolist: Denied rida näitab proovinud mängija ID-d (fivem:… ja steam:…)."},"nl":{"dc_denied_2":"Zet FiveM ID op je eigen ID, zoals de regel hieronder. Je vindt die in de serverconsole: de regel met Denied toont de ID van de speler die het probeerde (fivem:… en steam:…)."},"pl":{"dc_denied_2":"Ustaw FiveM ID na swoje własne ID, jak w linii poniżej. Znajdziesz je w konsoli serwera: linia z Denied pokazuje ID gracza, który próbował (fivem:… i steam:…)."},"pt":{"dc_denied_2":"Define o FiveM ID com o teu próprio ID, como a linha abaixo. Encontras-o na consola do servidor: a linha que diz Denied mostra o ID do jogador que tentou (fivem:… e steam:…)."},"tr":{"dc_denied_2":"FiveM ID alanına kendi ID'ni yaz, aşağıdaki satır gibi. Onu sunucu konsolunda bulursun: Denied yazan satır, deneyen oyuncunun ID'sini gösterir (fivem:… ve steam:…)."},"cn":{"dc_denied_2":"把 FiveM ID 设置为你自己的 ID，如下面这一行。可以在服务器控制台找到：显示 Denied 的那一行会给出尝试打开菜单的玩家 ID（fivem:… 和 steam:…）。"},"ta":{"dc_denied_2":"FiveM ID ஐ உங்கள் சொந்த ID ஆக அமைக்கவும், கீழே உள்ள வரி போல. அதை சர்வர் கன்சோலில் காணலாம்: Denied என்று சொல்லும் வரி முயன்ற வீரரின் ID ஐக் காட்டும் (fivem:… மற்றும் steam:…)."}};var N=window.I18N_N=window.I18N_N||{};for(var c in D){N[c]=N[c]||{};for(var k in D[c])N[c][k]=D[c][k];}})();
